/*
 * The edge tests of std's u128 forms (the port text's section 3): from_u64,
 * <, the checked - and *, the folded <<, and Display, at zero, one, the halves' edges,
 * the maximum, and a mixed value, each against Rust 1.99.1's own result,
 * which a Rust program printed into these tables; an overflowing - or *
 * panics with Rust's message in the cassert build, and wraps as release
 * Rust's does elsewhere.
 */
#include "postgres.h"

#include "doltgres/std/fmt.h"
#include "doltgres/std/int128.h"
#include "doltgres/std/unwind.h"

/* Int128FromCase is a from_u64 case: the value and Rust's u128. */
typedef struct Int128FromCase
{
	uint64		x;
	StdU128		expected;
} Int128FromCase;

/*
 * Int128BinaryCase is a two-operand case: the operands, Rust's <, Rust's
 * checked - and *, None as overflowed, and Rust's wrapping - and *, which
 * the forms give without overflow checks.
 */
typedef struct Int128BinaryCase
{
	StdU128		a;
	StdU128		b;
	bool		lt;
	bool		sub_overflows;
	StdU128		sub;
	bool		mul_overflows;
	StdU128		mul;
	StdU128		wrapping_sub;
	StdU128		wrapping_mul;
} Int128BinaryCase;

/* Int128DisplayCase is a Display case: the value and Rust's decimal text. */
typedef struct Int128DisplayCase
{
	StdU128		a;
	const char *expected;
} Int128DisplayCase;

/* Int128ShlCase is a << case: the value, the constant count, and Rust's result. */
typedef struct Int128ShlCase
{
	StdU128		a;
	uint32		n;
	StdU128		expected;
} Int128ShlCase;

/* INT128_FROM_CASES are from_u64's cases. */
static const Int128FromCase INT128_FROM_CASES[] = {
	{0x0, {0x0000000000000000, 0x0000000000000000}},
	{0x1, {0x0000000000000000, 0x0000000000000001}},
	{0xffffffffffffffff, {0x0000000000000000, 0xffffffffffffffff}},
};

